/*selectMasterMpRqQuotationDmSendPopList*/
SELECT	DISTINCT
		A.BTOA_USER_ID,
		(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.BTOA_USER_ID) AS RECV_NAME,
		(SELECT EMAIL FROM ICOMLUSR WHERE USER_ID = A.BTOA_USER_ID) AS EMAIL,
		(SELECT MOBILE_PHONE FROM ICOMLUSR WHERE USER_ID = A.BTOA_USER_ID) AS MOBILE
FROM	KEPRQDT A
WHERE	1=1
AND		BUYER = #{st_buyer}
AND		QUOTATION_NO = #{st_quotation_no}

