/*updateMasterMpRqQuotationDmSendDelSchdDate*/

	UPDATE	KEPRQDT
	SET		DELETE_SCHD_DATE = F_GET_WORKINGDAY(TO_CHAR(SYSDATE, 'YYYYMMDD'), 11)
	WHERE	1=1
	AND		BUYER = #{st_buyer}
	AND		QUOTATION_NO = #{st_quotation_no}
	AND		QUOTATION_SEQ = #{QUOTATION_SEQ}
	AND		REVISION = (SELECT REVISION FROM KEPRQDT WHERE BUYER = #{st_buyer} AND QUOTATION_NO = #{st_quotation_no} AND QUOTATION_SEQ = #{QUOTATION_SEQ})
